import React, { useState } from "react";
import MonitoringWidget from "../components/MonitoringWidget";

const AdminDashboard = () => {
  const [darkMode, setDarkMode] = useState(false);

  const handleToggleDarkMode = () => {
    setDarkMode((prev) => !prev);
    document.body.style.backgroundColor = darkMode ? "#fff" : "#1e293b";
    document.body.style.color = darkMode ? "#000" : "#fff";
  };

  return (
    <div
      className={`min-h-screen p-6 transition-all ${
        darkMode ? "bg-gray-900 text-white" : "bg-gray-100 text-gray-900"
      }`}
    >
      {/* Header Section */}
      <div className="flex flex-col items-center mb-6">
        <h1 className="text-3xl font-bold">Admin Dashboard</h1>
        <button
          onClick={handleToggleDarkMode}
          className={`mt-4 px-6 py-2 font-semibold rounded-lg shadow-md transition-all ${
            darkMode ? "bg-yellow-500 text-black" : "bg-green-500 text-white"
          }`}
        >
          Toggle {darkMode ? "Light" : "Dark"} Mode
        </button>
      </div>

      {/* Dashboard Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {/* Monitoring Widget */}
        <div className="p-6 bg-white dark:bg-gray-800 shadow-lg rounded-lg border border-gray-200 dark:border-gray-700">
          <h2 className="text-xl font-semibold mb-2">Server Metrics</h2>
          <MonitoringWidget />
        </div>

        {/* Placeholder for Additional Widgets */}
        <div className="p-6 bg-white dark:bg-gray-800 shadow-lg rounded-lg border border-gray-200 dark:border-gray-700">
          <h2 className="text-xl font-semibold mb-2">Other Metrics (Coming Soon)</h2>
          <p className="text-gray-500 dark:text-gray-400">
            More insights will be displayed here.
          </p>
        </div>

        {/* Alerts or Logs */}
        <div className="p-6 bg-white dark:bg-gray-800 shadow-lg rounded-lg border border-gray-200 dark:border-gray-700">
          <h2 className="text-xl font-semibold mb-2">System Logs</h2>
          <ul className="text-gray-600 dark:text-gray-400">
            <li>✔ Server Started Successfully</li>
            <li>⚠ High Memory Usage Detected</li>
            <li>✔ Database Connection Established</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default AdminDashboard;
